export function pathNetwork(plans){const nodes=[],key=p=>`${p.x.toFixed(4)},${p.z.toFixed(4)}`,map=new Map(),segments=[];function add(p){const k=key(p);if(!map.has(k)){map.set(k,nodes.length);nodes.push({...p,edges:[]});}return map.get(k);}
 for(const plan of plans)for(const path of plan.paths){const pts=path.points.map(p=>({x:p.x+plan.center.x,z:p.z+plan.center.z}));pts.forEach(add);for(let i=1;i<pts.length;i++)segments.push([pts[i-1],pts[i]]);}
 for(const [a,b]of segments){const dx=b.x-a.x,dz=b.z-a.z,len=dx*dx+dz*dz;if(!len)continue;const on=[];nodes.forEach((p,i)=>{const t=((p.x-a.x)*dx+(p.z-a.z)*dz)/len;if(t>=-.0001&&t<=1.0001&&Math.hypot(p.x-a.x-t*dx,p.z-a.z-t*dz)<.04)on.push({i,t});});on.sort((a,b)=>a.t-b.t);for(let j=1;j<on.length;j++){const u=on[j-1].i,v=on[j].i,w=Math.hypot(nodes[u].x-nodes[v].x,nodes[u].z-nodes[v].z);nodes[u].edges.push({v,w});nodes[v].edges.push({v:u,w});}}
 function nearest(p){let index=-1,best=Infinity;nodes.forEach((n,i)=>{const d=Math.hypot(p.x-n.x,p.z-n.z);if(d<best){best=d;index=i;}});return index;}
 return {nodes,route(a,b){const start=nearest(a),end=nearest(b);if(start<0||end<0)return null;const cost=nodes.map(()=>Infinity),prev=[],seen=new Set();cost[start]=0;while(seen.size<nodes.length){let u=-1;cost.forEach((c,i)=>{if(!seen.has(i)&&(u<0||c<cost[u]))u=i;});if(u<0||!Number.isFinite(cost[u]))return null;if(u===end){const path=[];for(let n=end;n!==undefined;n=prev[n])path.unshift({x:nodes[n].x,z:nodes[n].z});return path;}seen.add(u);for(const {v,w}of nodes[u].edges)if(cost[u]+w<cost[v]){cost[v]=cost[u]+w;prev[v]=u;}}return null;}};
}
